-- Competitor monitoring -- implements the previously-unused
-- intents.kind = 'monitor_competitor' path.
--
-- competitors: the small hand-picked list of stores an org wants tracked.
-- Members manage this list themselves (it's just metadata: name/url/notes).
--
-- competitor_snapshots: one row per monitoring run per competitor. Insights
-- are generated by diffing the latest snapshot against the previous one and
-- against the org's own current pricing -- system-generated, so read-only
-- for members like sources/insights.

create table public.competitors (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.orgs(id) on delete cascade,
  name text not null check (char_length(name) between 1 and 200),
  url text not null check (char_length(url) between 1 and 2048),
  niche_notes text check (niche_notes is null or char_length(niche_notes) <= 2000),
  created_at timestamptz not null default now()
);

create index competitors_org_idx on public.competitors (org_id);

alter table public.competitors enable row level security;

create policy "competitors_member_read"
  on public.competitors for select
  to authenticated
  using (public.is_member_of(org_id));

create policy "competitors_member_write"
  on public.competitors for insert
  to authenticated
  with check (public.is_member_of(org_id));

create policy "competitors_member_update"
  on public.competitors for update
  to authenticated
  using (public.is_member_of(org_id))
  with check (public.is_member_of(org_id));

create policy "competitors_member_delete"
  on public.competitors for delete
  to authenticated
  using (public.is_member_of(org_id));

create table public.competitor_snapshots (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.orgs(id) on delete cascade,
  competitor_id uuid not null references public.competitors(id) on delete cascade,
  captured_at timestamptz not null default now(),
  product_count integer check (product_count is null or product_count >= 0),
  price_points jsonb not null default '[]'::jsonb,
  source text not null check (source in ('tavily', 'scrape'))
);

create index competitor_snapshots_org_idx on public.competitor_snapshots (org_id, captured_at desc);
create index competitor_snapshots_competitor_idx on public.competitor_snapshots (competitor_id, captured_at desc);

alter table public.competitor_snapshots enable row level security;

create policy "competitor_snapshots_member_read"
  on public.competitor_snapshots for select
  to authenticated
  using (public.is_member_of(org_id));

-- Writes only via service_role (workers).

select pgmq.create('q:monitor');
